tool_calls.raw:
{"command": "cd ~ && python3 - <<'EOF'
import workcell
for dz in ["1","1","1","1","1","1","-0.5","-1","-1","-1"]:
    r=workcell.call("arm","step",dz); s=workcell.call("arm","status"); f=workcell.call("ft","read","300")
    print(dz, r.text.splitlines()[0], "|", s.text.splitlines()[0], "|", f.text)
EOF"}

args.command:
cd ~ && python3 - <<'EOF'
import json
rows=json.load(open("series.json"))+[None]
for r in json.load(open("series.json")):
    d=r[2]; 
    if d['fz']>1: print(r[0], r[1]['tip_mm'], "Fx/Fz=%.4f"%(d['fx']/d['fz']), "Fy/Fz=%.4f"%(d['fy']/d['fz']))
for r in json.load(open("rows.json")):
    s,d=r
    if d and d['fz']>1: print("old", s, "Fx/Fz=%.4f"%(d['fx']/d['fz']))
EOF

